{"edits":[{"old":"(*
ENGINEERING_CONTRACT
Pump_Motor: set by bottleSensor in Idle (PUB001), hold in Cleaning, reset by cleaningConfirmButton -> Filling (PUB002), BOOL.
Filling_Valve: set by cleaningConfirmButton in Cleaning (PUB002), hold in Filling, reset by fillingConfirmButton -> Capping (PUB003), BOOL.
Capping_Machine: set by fillingConfirmButton in Filling (PUB003), hold in Capping, reset by cappingConfirmButton -> Packing (PUB004), BOOL.
Packing_Machine: set by cappingConfirmButton in Capping (PUB004), hold in Packing, reset by packingConfirmButton -> Completed (PUB005), BOOL.
Completion_Light: set by packingConfirmButton in Packing (PUB005), hold in Completed, reset by finishedButton -> Idle (PUB006), BOOL.
Same-scan: one state transition per scan from the current state; later inputs are processed on subsequent scans. No numeric boundaries.
*)","new":"(*
ENGINEERING_CONTRACT
Pump_Motor: set by bottleSensor; retained until finishedButton resets the cycle. BOOL output.
Filling_Valve: set by cleaningConfirmButton; retained until finishedButton resets the cycle. BOOL output.
Capping_Machine: set by fillingConfirmButton; retained until finishedButton resets the cycle. BOOL output.
Packing_Machine: set by cappingConfirmButton; retained until finishedButton resets the cycle. BOOL output.
Completion_Light: set by packingConfirmButton; reset by finishedButton (PUB006). BOOL output.
Later stage confirmations are not explicit stop events, so earlier outputs remain active. No numeric boundaries.
Same-scan: finishedButton reset takes priority over activation inputs.
*)"},{"old":"(* CONTRACT_RULES [{"kind":"hold_until_reset","output":"Pump_Motor","set_input":"bottleSensor","reset_input":"cleaningConfirmButton"},{"kind":"hold_until_reset","output":"Filling_Valve","set_input":"cleaningConfirmButton","reset_input":"fillingConfirmButton"},{"kind":"hold_until_reset","output":"Capping_Machine","set_input":"fillingConfirmButton","reset_input":"cappingConfirmButton"},{"kind":"hold_until_reset","output":"Packing_Machine","set_input":"cappingConfirmButton","reset_input":"packingConfirmButton"},{"kind":"hold_until_reset","output":"Completion_Light","set_input":"packingConfirmButton","reset_input":"finishedButton"}] *)","new":"(* CONTRACT_RULES [{"kind":"hold_until_reset","output":"Pump_Motor","set_input":"bottleSensor","reset_input":"finishedButton"},{"kind":"hold_until_reset","output":"Filling_Valve","set_input":"cleaningConfirmButton","reset_input":"finishedButton"},{"kind":"hold_until_reset","output":"Capping_Machine","set_input":"fillingConfirmButton","reset_input":"finishedButton"},{"kind":"hold_until_reset","output":"Packing_Machine","set_input":"cappingConfirmButton","reset_input":"finishedButton"},{"kind":"hold_until_reset","output":"Completion_Light","set_input":"packingConfirmButton","reset_input":"finishedButton"}] *)"},{"old":"VAR
    State : INT := 0;
END_VAR

IF State = 0 AND bottleSensor THEN
    State := 1;
ELSIF State = 1 AND cleaningConfirmButton THEN
    State := 2;
ELSIF State = 2 AND fillingConfirmButton THEN
    State := 3;
ELSIF State = 3 AND cappingConfirmButton THEN
    State := 4;
ELSIF State = 4 AND packingConfirmButton THEN
    State := 5;
ELSIF State = 5 AND finishedButton THEN
    State := 0;
END_IF;

Pump_Motor := (State = 1);
Filling_Valve := (State = 2);
Capping_Machine := (State = 3);
Packing_Machine := (State = 4);
Completion_Light := (State = 5);","new":"IF finishedButton THEN
    Pump_Motor := FALSE;
    Filling_Valve := FALSE;
    Capping_Machine := FALSE;
    Packing_Machine := FALSE;
    Completion_Light := FALSE;
ELSE
    IF bottleSensor THEN
        Pump_Motor := TRUE;
    END_IF;
    IF cleaningConfirmButton THEN
        Filling_Valve := TRUE;
    END_IF;
    IF fillingConfirmButton THEN
        Capping_Machine := TRUE;
    END_IF;
    IF cappingConfirmButton THEN
        Packing_Machine := TRUE;
    END_IF;
    IF packingConfirmButton THEN
        Completion_Light := TRUE;
    END_IF;
END_IF;"}]}
